import { readFile, mkdir, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import Ajv from 'ajv';
import standaloneCode from 'ajv/dist/standalone/index.js';
import { SCHEMA } from '../src/policy.ts';

export function contractArtifacts() {
  const ajv = new Ajv({ strict: true, allErrors: false, code: { source: true, esm: true, lines: true } });
  const validate = ajv.compile(SCHEMA);
  return {
    'schemas/roadmap-status.schema.json': JSON.stringify(SCHEMA, null, 2) + '\n',
    'generated/snapshot-validator.mjs': '// Generated by npm run prepare:contract; do not edit.\n' + standaloneCode(ajv, validate) + '\n',
  };
}

export async function checkArtifacts() {
  for (const [path, expected] of Object.entries(contractArtifacts())) {
    if (await readFile(new URL('../' + path, import.meta.url), 'utf8') !== expected) throw new Error('Generated contract drift');
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  for (const [path, value] of Object.entries(contractArtifacts())) {
    const url = new URL('../' + path, import.meta.url);
    await mkdir(new URL('./', url), { recursive: true });
    await writeFile(url, value, 'utf8');
  }
}
